"use client";

/**
 * GameHero — an animated, per-game-themed hero for the game-server SEO landing
 * pages. It renders the SAME content structure as <PageHero> (logo → eyebrow →
 * title+highlight → sub → CTAs) so copy and layout stay identical across pages,
 * but sits it on a live themed particle field coloured by the game's own brand
 * gradient (GAME_VISUAL in GameLogo.tsx).
 *
 * The motion is per-game: Minecraft/Bedrock drift like voxels, Valheim/Enshrouded
 * and Project Zomboid fall like snow/ash, Rust/7DTD/Factorio rise like embers.
 * Everything is coloured from the family's from/to stops, so a new game "just
 * works" the moment it has a GAME_VISUAL entry — no per-page art.
 *
 * Performance + a11y: one capped requestAnimationFrame loop on a DPR-scaled
 * canvas, paused when the hero scrolls out of view; under prefers-reduced-motion
 * (or with no canvas support) it renders a static themed aura and never animates.
 */

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { Eyebrow } from "@/components/marketing/primitives";
import { GameLogo, GAME_VISUAL } from "@/components/marketing/GameLogo";
import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";

type Cta = { label: string; href: string };

type Motif = "rise" | "fall" | "drift";

/** How each family's particles move. Falls back to "drift". */
const MOTIF: Record<string, Motif> = {
  minecraft: "drift",
  bedrock: "drift",
  valheim: "fall",
  enshrouded: "fall",
  theforest: "fall",
  sonsoftheforest: "fall",
  projectzomboid: "fall",
  vrising: "fall",
  rust: "rise",
  sdtd: "rise",
  conan: "rise",
  cs2: "rise",
  factorio: "rise",
  palworld: "drift",
  terraria: "drift",
  ark: "drift",
  satisfactory: "drift",
  gmod: "drift",
  unturned: "drift",
};

/** Families whose particles read better as little squares (voxel / pixel / industrial). */
const SQUARE = new Set(["minecraft", "bedrock", "factorio", "terraria", "satisfactory"]);

type P = { x: number; y: number; r: number; vx: number; vy: number; a: number; rot: number; vr: number };

export function GameHero({
  family,
  eyebrow = "Game servers",
  title,
  highlight,
  sub,
  primary,
  secondary,
}: {
  family: string;
  eyebrow?: string;
  title: React.ReactNode;
  highlight?: string;
  sub?: React.ReactNode;
  primary?: Cta;
  secondary?: Cta;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const visual = GAME_VISUAL[family] ?? { from: "#334155", to: "#64748b" };
  const motif = MOTIF[family] ?? "drift";
  const square = SQUARE.has(family);
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;
  const [heroFailed, setHeroFailed] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return; // static aura only

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const hexToRgb = (hex: string) => {
      const h = hex.replace("#", "");
      const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
      return [(n >> 16) & 255, (n >> 8) & 255, n & 255] as const;
    };
    const [fr, fg, fb] = hexToRgb(visual.from);
    const [tr, tg, tb] = hexToRgb(visual.to);

    let w = 0;
    let h = 0;
    let dpr = 1;
    let particles: P[] = [];
    let raf = 0;
    let running = true;

    const seed = (p: P, initial: boolean) => {
      p.r = 1 + Math.random() * (square ? 4 : 3);
      p.a = 0.15 + Math.random() * 0.45;
      p.rot = Math.random() * Math.PI;
      p.vr = (Math.random() - 0.5) * 0.02;
      const speed = 0.15 + Math.random() * 0.5;
      if (motif === "rise") {
        p.x = Math.random() * w;
        p.y = initial ? Math.random() * h : h + 10;
        p.vx = (Math.random() - 0.5) * 0.25;
        p.vy = -speed;
      } else if (motif === "fall") {
        p.x = Math.random() * w;
        p.y = initial ? Math.random() * h : -10;
        p.vx = (Math.random() - 0.5) * 0.35;
        p.vy = speed;
      } else {
        p.x = Math.random() * w;
        p.y = Math.random() * h;
        const ang = Math.random() * Math.PI * 2;
        p.vx = Math.cos(ang) * speed * 0.5;
        p.vy = Math.sin(ang) * speed * 0.5;
      }
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = rect.width;
      h = rect.height;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      // Density scales with area but is capped so big screens stay cheap.
      const count = Math.min(90, Math.round((w * h) / 14000));
      particles = Array.from({ length: count }, () => {
        const p: P = { x: 0, y: 0, r: 0, vx: 0, vy: 0, a: 0, rot: 0, vr: 0 };
        seed(p, true);
        return p;
      });
    };

    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      for (const p of particles) {
        p.x += p.vx;
        p.y += p.vy;
        p.rot += p.vr;
        // recycle when off-canvas
        if (p.y < -12 || p.y > h + 12 || p.x < -12 || p.x > w + 12) seed(p, false);
        // colour: lerp between the two brand stops by vertical position
        const t = Math.max(0, Math.min(1, p.y / h));
        const r = Math.round(fr + (tr - fr) * t);
        const g = Math.round(fg + (tg - fg) * t);
        const b = Math.round(fb + (tb - fb) * t);
        ctx.globalAlpha = p.a;
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        if (square) {
          ctx.save();
          ctx.translate(p.x, p.y);
          ctx.rotate(p.rot);
          ctx.fillRect(-p.r, -p.r, p.r * 2, p.r * 2);
          ctx.restore();
        } else {
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
      if (running) raf = requestAnimationFrame(draw);
    };

    resize();
    running = true;
    raf = requestAnimationFrame(draw);

    const onResize = () => resize();
    window.addEventListener("resize", onResize);

    // Pause the loop when the hero is scrolled away (saves battery/CPU).
    const io =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver(
            ([e]) => {
              if (e.isIntersecting && !running) {
                running = true;
                raf = requestAnimationFrame(draw);
              } else if (!e.isIntersecting && running) {
                running = false;
                cancelAnimationFrame(raf);
              }

