import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, migrated from the old
 * <GameLandingPage/> template (2026-08-31).
 *
 * Real pricing/metadata/JSON-LD are unchanged from the previous hand-rolled
 * version of this page: Standard 4 GB $12.99, Pro 8 GB $20.99 (popular),
 * Max 16 GB $32.99 — these match PREVIEW_GAMES.gmod exactly, so no price
 * override was needed. Garry's Mod is the SELF-MANAGED VPS product line
 * (full root over SSH), not a managed game-panel product, so plans carry
 * vCPU/NVMe meta rather than slot counts — same pattern as Satisfactory's
 * PreviewGame entry.
 *
 * The FAQ + related-links sections below the flagship template are carried
 * over verbatim from the previous page (same copy) since GameLandingCombined
 * doesn't render its own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "Garry's Mod Server Hosting on a VPS",
  description:
    "Garry's Mod server hosting on a Nxeon VPS. Full root access, NVMe SSD, DDoS protection and a dedicated IPv4 to run DarkRP, TTT or Sandbox with Workshop addons. From $12.99/mo.",
  alternates: { canonical: "/garrys-mod-server-hosting" },
  openGraph: {
    type: "article",
    title: "Garry's Mod Server Hosting on a VPS",
    description:
      "Run your own Garry's Mod server on a Nxeon VPS — DarkRP, TTT, Sandbox, Workshop addons, full root, DDoS protection. From $12.99/mo.",
    url: `${APP_URL}/garrys-mod-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.gmod;

const FAQ = [
  {
    q: "What are the requirements for a Garry's Mod server?",
    a: "GMod is CPU-led and moderate on RAM — a 2.5 GHz+ core and around 8 GB of RAM is a comfortable baseline for a busy DarkRP or TTT server with addons. Our Pro 8 GB VPS is the popular pick; a small sandbox server runs fine on 4 GB.",
  },
  {
    q: "Do I need a GSLT to run a GMod server?",
    a: "For a public server, yes — a Game Server Login Token under app ID 4000. It takes a minute to create in Steam and lets your server appear in the public browser. Our setup guide covers it.",
  },
  {
    q: "How do I install Workshop addons?",
    a: "You set a host_workshop_collection in your server config so the server pulls a Workshop collection on start, and configure FastDL (sv_downloadurl) so players download content quickly. With full root you set all of this up yourself.",
  },
  {
    q: "Do I need Counter-Strike: Source content?",
    a: "Many popular addons and maps reference CS:S textures and models, so mounting CS:S content is a common step to avoid missing textures (the pink-and-black error). Our addons guide explains how to mount it.",
  },
  {
    q: "Can I run DarkRP, TTT, or Sandbox?",
    a: "Any of them. With full root access you install the gamemode and its addons, edit server.cfg and Lua configs, and switch modes freely — nothing is locked down.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "CS2 server hosting", href: "/cs2-server-hosting" },
  { label: "FiveM server hosting", href: "/fivem-server-hosting" },
  { label: "Gaming VPS", href: "/gaming-vps" },
  { label: "Pricing", href: "/pricing" },
];

export default function GarrysModServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Garry's Mod Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

